<?php
declare(strict_types=1);namespace Atlas\Platform\Core\Audit;use RuntimeException;final class WordPressAuditRecorder implements AuditRecorder{public function __construct(private object$db){}public function record(string$event,string$module,int$actorId,?string$organizationId,string$objectType,string$objectId,array$context=[]):void{$ok=$this->db->insert($this->db->prefix.'atlas_audit_events',['id'=>wp_generate_uuid_4(),'event_name'=>$event,'module'=>$module,'actor_user_id'=>$actorId,'organization_id'=>$organizationId,'object_type'=>$objectType,'object_id'=>$objectId,'context_json'=>wp_json_encode($context),'occurred_at'=>current_time('mysql',true)]);if($ok===false){throw new RuntimeException('Atlas audit event could not be recorded.');}}}
